-- ================================================================
-- Bahrain (BH) ES/DE/FR translations, completing 485 (milestone)
-- and 487 (deep-dive content) against their English content.
-- Written 10 Aug 2026. milestone_translations has a natural string
-- PK (milestone_id), so those rows are plain INSERT OR IGNORE
-- statements keyed on the hardcoded id string from 485 -- no JOIN
-- needed. deep_dive_page_translations is keyed on (country_id,
-- lang) via a SELECT against countries.code. The autoincrement
-- deep_dive_stats/cards/steps/portals translation tables have no
-- natural key, so every row here is looked up via a JOIN on
-- stable identifying columns (country code + section/sort_order,
-- or country code + stable url for portals) -- never via
-- (SELECT MAX(id) ...). INSERT OR IGNORE throughout. Bahrain has
-- no launch story -- nothing newsworthy has happened -- so no
-- story_translations rows are written here.
--
-- The "no mandate / voluntary only / preparatory work only"
-- framing from the EN content is preserved with equal clarity in
-- every language -- no translation implies a mandate exists, is
-- proposed, or is imminent where the English does not say so.
--
-- Kept unchanged across languages: proper nouns and official names
-- (NBR, GCC, ZATCA, Peppol, BHD). VAT General Guide is rendered as
-- a conventionally-translated document-title reference per
-- language (e.g. "Guía General del IVA" es / "VAT General Guide"
-- kept as-is de/fr where no stable localized title exists).
-- mandate_summary_icon is always '📝', untranslated in every
-- language. Dates localized per language convention: "16 Nov
-- 2023" -> "16 de noviembre de 2023" (es) / "16. November 2023"
-- (de) / "16 novembre 2023" (fr).
-- ================================================================


-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'Sin mandato — la facturación electrónica sigue siendo enteramente voluntaria, sin proyecto de ley, propuesta ni calendario de ningún tipo',
  'Esta página de análisis en profundidad refleja el régimen de facturación electrónica de Baréin, confirmado a través de la propia Guía General del IVA de la Oficina Nacional de Ingresos (NBR), dos rastreadores profesionales independientes (EY, Aurifer) y los propios registros de la Junta de Licitaciones de Baréin, con fecha de 10 de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Baréin no tiene ningún mandato de facturación electrónica, ningún proyecto de ley ni ningún calendario publicado oficialmente de ningún tipo — todo lo que figura en esta página describe una práctica voluntaria y actividad gubernamental preparatoria, no un requisito vigente o próximo. Confirme el estado actual directamente con la Oficina Nacional de Ingresos de Baréin (nbr.gov.bh) o con un asesor fiscal bareiní cualificado antes de basar en esta página sus decisiones de planificación.',
  'El único evento fechado y confirmado por fuentes primarias en esta cronología es un cambio de procedimiento menor: el 16 de noviembre de 2023, la NBR eliminó el requisito de que las empresas obtuvieran una aprobación previa antes de emitir voluntariamente facturas electrónicas. Eso es todo — no hay ningún otro hito específico de facturación electrónica, anterior o posterior, que mostrar, porque no ha ocurrido nada más. Dos rastreadores profesionales independientes consultados directamente a mediados de 2026 (EY, Aurifer) siguen clasificando a Baréin como un país sin ningún mandato aplicable y en fase de "trabajo preparatorio" únicamente.',
  'No existe ningún formato, esquema ni estándar técnico de facturación electrónica para Baréin, porque la facturación electrónica es enteramente voluntaria y no está regulada más allá de las normas ordinarias de facturación del IVA. No existe ninguna plataforma de facturación electrónica de la NBR, y se ha confirmado que Baréin no es miembro de Peppol.',
  'Nunca se ha definido ningún alcance para un mandato de facturación electrónica bareiní, porque nunca se ha propuesto ningún mandato. Las normas ordinarias de facturación del IVA se aplican de manera uniforme en B2B, B2G y B2C, sin ningún requisito de formato electrónico de ningún tipo.',
  'No hay nada que cumplir hoy, ni nada en el horizonte con una fecha publicada. Los pasos que figuran a continuación describen cómo mantenerse informado dado que los vecinos de Baréin están avanzando en materia de facturación electrónica, no cómo cumplir con un requisito que no existe.',
  'Nunca se ha propuesto ni publicado ningún régimen de sanciones específico de la facturación electrónica, ya que no existe ningún requisito de facturación electrónica al que asociar una sanción. Baréin sí cuenta con sanciones generales de la ley del IVA que cubren cuestiones no relacionadas (presentación tardía, fallos de registro, infracciones del procedimiento de facturación, evasión fiscal) — se mencionan a continuación por motivos de exhaustividad, pero no son sanciones de facturación electrónica, y las cifras concretas no se volvieron a verificar de forma independiente frente al texto primario de la ley del IVA en esta ronda de investigación.',
  'Baréin no tiene ningún mandato de facturación electrónica, ningún proyecto de ley ni ningún calendario publicado oficialmente de ningún tipo. El único hecho confirmado y fechado es un cambio de procedimiento menor de noviembre de 2023: la NBR eliminó el requisito de solicitar una aprobación previa antes de emitir voluntariamente facturas electrónicas — la facturación electrónica sigue siendo enteramente voluntaria. Dos rastreadores profesionales independientes consultados a mediados de 2026 (EY, Aurifer) clasifican ambos a Baréin como un país que sigue en "trabajo preparatorio", junto con Kuwait, mientras que Arabia Saudita, los EAU y Omán cuentan todos con mandatos activos o inminentes, y Catar ha al menos aprobado un proyecto de ley. Una licitación gubernamental de 2023 para una plataforma de facturación electrónica, y un reporte no confirmado de una nueva licitación en 2025, sugieren actividad preparatoria entre bastidores, pero ninguna de las dos es una ley. Este rastreador se actualizará de inmediato en cuanto se publique oficialmente cualquier propuesta real, proyecto de ley o calendario.',
  '📝'
FROM countries WHERE code = 'BH';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Sin mandato', 'Estado de la ley de facturación electrónica' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Solo voluntaria', 'Base actual de la facturación electrónica en Baréin' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '16 nov. 2023', 'La NBR elimina el requisito de aprobación previa para la facturación electrónica voluntaria' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'Ninguno publicado', 'Propuesta de mandato, proyecto de ley o calendario de cualquier tipo' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '"Trabajo preparatorio"', 'Según los propios rastreadores de EY y Aurifer, ambos de mediados de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'No existe ningún formato — porque la facturación electrónica sigue siendo voluntaria', NULL, NULL, 'Baréin nunca ha publicado ningún esquema de facturación electrónica, ningún estándar XML/UBL ni ninguna especificación técnica. No existe ninguna plataforma de facturación electrónica de la NBR, y se ha confirmado que Baréin no es miembro de la red Peppol. Las empresas que emiten voluntariamente facturas electrónicas lo hacen en sus propios sistemas, conforme a las normas ordinarias de facturación del IVA, no a ningún formato específico de facturación electrónica.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Qué está cubierto hoy', '[["B2B", "No definido -- no existe ningún mandato"], ["B2G", "No definido -- no existe ningún mandato"], ["B2C", "No definido -- no existe ningún mandato"], ["Facturación electrónica voluntaria", "Permitida sin aprobación previa de la NBR desde el 16 de noviembre de 2023"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Señales preparatorias, no un mandato', '[["Licitación de plataforma de 2023", "Confirmada a través de la propia Junta de Licitaciones de Baréin (305/2023/BTB): un contrato de 54 meses para diseñar/operar una plataforma de facturación electrónica"], ["Licitación de 2025 (reportada)", "Un informe sectorial señaló una nueva licitación para un sistema B2B a escala nacional -- no se pudo corroborar de forma independiente en esta ronda"], ["Modelo previsto", "Los comentarios del sector especulan con un enfoque al estilo de la ZATCA saudita -- no se trata de una decisión oficial del gobierno bareiní"], ["Membresía en Peppol", "Baréin no es miembro de Peppol"]]', 'Una licitación gubernamental para construir una plataforma es una actividad preparatoria real, pero no es una ley, un mandato ni un requisito legal fechado -- se incluye aquí por motivos de exhaustividad, no como prueba de que un mandato sea inminente.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚖️ No existe ningún régimen de sanciones de facturación electrónica', NULL, NULL, 'No hay nada que sancionar en el ámbito de la facturación electrónica: Baréin nunca ha legislado un mandato de facturación electrónica, por lo que no existe ningún régimen de multas o sanciones vinculado a cómo (o si) se emiten facturas electrónicamente.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📋 Las sanciones generales del IVA de Baréin (no relacionadas con la facturación electrónica)', NULL, NULL, 'La ley ordinaria del IVA de Baréin conlleva sus propias sanciones generales -- presentación/pago tardíos (5-25 % del impuesto adeudado), falta de registro (multa de hasta BHD 10.000), infracciones del procedimiento de facturación (multa de hasta BHD 5.000), y evasión fiscal, incluida la no emisión de facturas (prisión más multas). Estas se aplican al cumplimiento del IVA en términos generales y no son específicas de la facturación electrónica; las cifras proceden de una fuente secundaria de cumplimiento y no se volvieron a verificar de forma independiente frente al texto primario de la ley del IVA en esta ronda de investigación.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🌍 Contexto: uno de los dos estados del CCG sin ningún mandato en absoluto', NULL, NULL, 'El sistema Fatoora de Arabia Saudita está en funcionamiento y consolidado; los EAU están implementando de forma gradual un mandato B2B basado en Peppol desde julio de 2026; Omán cuenta con un piloto en funcionamiento; Catar aprobó un proyecto de ley el 6 de mayo de 2026. Baréin y Kuwait son ahora los únicos dos estados del CCG que no han dado ningún paso formal hacia la facturación electrónica.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'No hay nada que cumplir hoy', 'En Baréin no existe ningún mandato de facturación electrónica, ni propuesto ni promulgado. No se requiere ningún registro, presentación ni cambio de formato.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'La facturación electrónica está disponible de forma voluntaria, sin necesidad de aprobación', 'Desde noviembre de 2023, cualquier empresa registrada a efectos del IVA puede emitir facturas electrónicas sin solicitar la aprobación previa de la NBR -- pero nada le obliga a hacerlo, y no se exige ningún formato ni plataforma en particular.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Esté atento a una propuesta real, no solo a una licitación', 'Baréin ha publicado licitaciones gubernamentales para infraestructura de plataformas de facturación electrónica, pero una licitación no es un mandato. Esté atento específicamente a un proyecto de modificación de la ley del IVA o a un anuncio de mandato de la NBR.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Espere que Baréin siga el precedente regional con el tiempo', 'Con Arabia Saudita, los EAU, Omán y ahora Catar avanzando en la facturación electrónica, es probable que Baréin acabe siguiendo su ejemplo -- pero nada confirma oficialmente un calendario, y esta página no especulará sobre ninguno.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Guarde esta página en sus favoritos', 'Este rastreador añadirá un hito real y un calendario de cumplimiento adecuado en el momento en que Baréin publique una propuesta real de facturación electrónica o un proyecto de ley.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'Oficina Nacional de Ingresos (NBR) -- administración general del IVA; sin contenido de mandato de facturación electrónica' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.nbr.gov.bh';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'Fonoa -- resumen de la eliminación del requisito de aprobación previa de noviembre de 2023 (fuente del sector, no publicada por el gobierno)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.fonoa.com/resources/blog/bahrain-eliminates-tax-authority-approval-requirement-for-e-invoice-issuance';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bh-prior-approval-removed-2023', 'es',
  'La NBR elimina el requisito de aprobación previa para la facturación electrónica voluntaria -- sigue sin existir un mandato',
  'El 16 de noviembre de 2023, la Oficina Nacional de Ingresos de Baréin (NBR) actualizó su Guía General del IVA (versión 1.8, sección 9.2) para permitir que las empresas registradas a efectos del IVA emitan facturas electrónicas sin necesidad de solicitar previamente la aprobación de la NBR. Se trata de un cambio de procedimiento real, fechado y confirmado por fuentes primarias -- pero eliminó un paso burocrático de preautorización para una práctica puramente voluntaria; no creó ningún mandato de facturación electrónica, ninguna plataforma, ningún requisito de formato ni ningún plazo. No existe ningún proyecto de ley, ninguna modificación de la ley del IVA ni ningún reglamento promulgado que establezca un mandato de facturación electrónica para Baréin a fecha de esta ronda de investigación (agosto de 2026). Dos rastreadores profesionales independientes consultados directamente -- el propio rastreador de novedades de facturación electrónica de EY (edición del 24 de junio de 2026) y Aurifer, un especialista en impuestos indirectos de Oriente Medio -- siguen clasificando a Baréin como un país sin ningún mandato aplicable y en fase de "trabajo preparatorio" únicamente. Una licitación gubernamental de 2023 para una plataforma de facturación electrónica, y reportes no confirmados de una nueva licitación en 2025, apuntan a actividad preparatoria entre bastidores, pero ninguna de las dos es una ley ni un requisito fechado.',
  '["No se requiere ninguna acción de cumplimiento -- la facturación electrónica sigue siendo totalmente voluntaria en Baréin, sin ningún mandato propuesto ni promulgado", "Vigile la Guía General del IVA de la NBR y la Gaceta Oficial por si apareciera alguna propuesta de mandato futura -- actualmente no existe ninguna", "Tenga en cuenta que Baréin es ahora el único estado del CCG, junto con Kuwait, sin ningún mandato de facturación electrónica activo ni inminente, dado que Arabia Saudita, los EAU, Omán y (en forma de proyecto de ley) Catar están todos avanzando"]'
);

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'Kein Mandat — die E-Rechnungsstellung bleibt vollständig freiwillig, ohne Gesetzentwurf, Vorschlag oder Zeitplan jeglicher Art',
  'Diese Analyseseite spiegelt Bahrains E-Invoicing-Regime wider, wie es über den eigenen VAT General Guide des National Bureau for Revenue (NBR), zwei unabhängige professionelle Tracker (EY, Aurifer) und die eigenen Unterlagen des bahrainischen Tender Board bestätigt wurde, mit Stand 10. August 2026, und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bahrain hat kein E-Invoicing-Mandat, keinen Gesetzentwurf und keinen offiziell veröffentlichten Zeitplan jeglicher Art — alles auf dieser Seite beschreibt freiwillige Praxis und vorbereitende staatliche Aktivität, keine geltende oder bevorstehende Anforderung. Bestätigen Sie den aktuellen Status direkt beim bahrainischen National Bureau for Revenue (nbr.gov.bh) oder bei einem qualifizierten bahrainischen Steuerberater, bevor Sie sich bei Planungsentscheidungen auf diese Seite verlassen.',
  'Das einzige datierte, durch Primärquellen bestätigte Ereignis auf dieser Zeitleiste ist eine geringfügige Verfahrensänderung: Am 16. November 2023 hob die NBR das Erfordernis auf, dass Unternehmen vor der freiwilligen Ausstellung elektronischer Rechnungen eine vorherige Genehmigung einholen müssen. Das ist alles — es gibt keinen früheren oder späteren E-Invoicing-spezifischen Meilenstein zu zeigen, weil sonst nichts geschehen ist. Zwei unabhängige professionelle Tracker, die Mitte 2026 direkt geprüft wurden (EY, Aurifer), stufen Bahrain weiterhin als Land ohne anwendbares Mandat ein, das sich lediglich in der "vorbereitenden Arbeit" befindet.',
  'Für Bahrain existiert kein E-Invoicing-Format, kein Schema und kein technischer Standard, da die E-Rechnungsstellung vollständig freiwillig und über die gewöhnlichen Mehrwertsteuer-Rechnungsvorschriften hinaus unreguliert ist. Es gibt keine NBR-E-Invoicing-Plattform, und es ist bestätigt, dass Bahrain kein Peppol-Mitglied ist.',
  'Für ein bahrainisches E-Invoicing-Mandat wurde nie ein Anwendungsbereich definiert, da nie ein Mandat vorgeschlagen wurde. Die gewöhnlichen Mehrwertsteuer-Rechnungsvorschriften gelten einheitlich für B2B, B2G und B2C, ohne jegliche Anforderung an ein elektronisches Format.',
  'Es gibt heute nichts zu erfüllen und nichts am Horizont mit einem veröffentlichten Datum. Die nachstehenden Schritte beschreiben, wie Sie angesichts der Fortschritte der Nachbarländer Bahrains bei der E-Rechnungsstellung informiert bleiben können — nicht, wie Sie eine Anforderung erfüllen, die es nicht gibt.',
  'Es wurde nie ein E-Invoicing-spezifischer Bußgeldkatalog vorgeschlagen oder veröffentlicht, da keine E-Invoicing-Anforderung besteht, an die eine Sanktion geknüpft werden könnte. Bahrain verfügt zwar über allgemeine Sanktionen des Mehrwertsteuerrechts für sachfremde Angelegenheiten (verspätete Einreichung, Registrierungsversäumnisse, Verstöße gegen Rechnungsverfahren, Steuerhinterziehung) — diese werden nachstehend der Vollständigkeit halber erwähnt, sind aber keine E-Invoicing-Sanktionen, und die konkreten Beträge wurden in dieser Rechercherunde nicht unabhängig gegen den primären Text des Mehrwertsteuergesetzes erneut verifiziert.',
  'Bahrain hat kein E-Invoicing-Mandat, keinen Gesetzentwurf und keinen offiziell veröffentlichten Zeitplan jeglicher Art. Die einzige bestätigte, datierte Tatsache ist eine geringfügige Verfahrensänderung vom November 2023: Die NBR hob das Erfordernis auf, vor der freiwilligen Ausstellung elektronischer Rechnungen eine vorherige Genehmigung einzuholen — die E-Rechnungsstellung bleibt vollständig freiwillig. Zwei unabhängige professionelle Tracker, die Mitte 2026 geprüft wurden (EY, Aurifer), stufen Bahrain beide weiterhin als in "vorbereitender Arbeit" befindlich ein, neben Kuwait, während Saudi-Arabien, die VAE und Oman allesamt aktive oder bevorstehende Mandate haben und Katar zumindest einen Gesetzentwurf verabschiedet hat. Eine staatliche Ausschreibung aus dem Jahr 2023 für eine E-Invoicing-Plattform sowie ein unbestätigter Bericht über eine weitere Ausschreibung 2025 deuten auf vorbereitende Aktivitäten im Hintergrund hin, sind aber beide kein Gesetz. Dieser Tracker wird umgehend aktualisiert, sobald ein tatsächlicher Vorschlag, Gesetzentwurf oder Zeitplan offiziell veröffentlicht wird.',
  '📝'
FROM countries WHERE code = 'BH';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Kein Mandat', 'Status des E-Invoicing-Gesetzes' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 0;
