INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '16. Nov. 2023', 'NBR hebt Genehmigungserfordernis für freiwillige E-Rechnungsstellung auf' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Keiner veröffentlicht', 'Mandatsvorschlag, Gesetzentwurf oder Zeitplan jeglicher Art' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '„Vorbereitende Arbeit"', 'Laut den eigenen Trackern von EY und Aurifer, beide Mitte 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Es existiert kein Format — weil die E-Rechnungsstellung freiwillig bleibt', NULL, NULL, 'Bahrain hat nie ein E-Invoicing-Schema, einen XML/UBL-Standard oder eine technische Spezifikation veröffentlicht. Es gibt keine NBR-E-Invoicing-Plattform, und es ist bestätigt, dass Bahrain kein Mitglied des Peppol-Netzwerks ist. Unternehmen, die freiwillig elektronische Rechnungen ausstellen, tun dies auf ihren eigenen Systemen nach den gewöhnlichen Mehrwertsteuer-Rechnungsvorschriften, nicht nach einem E-Invoicing-spezifischen Format.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was heute abgedeckt ist', '[["B2B", "Nicht definiert -- es besteht kein Mandat"], ["B2G", "Nicht definiert -- es besteht kein Mandat"], ["B2C", "Nicht definiert -- es besteht kein Mandat"], ["Freiwillige E-Rechnungsstellung", "Seit dem 16. November 2023 ohne vorherige NBR-Genehmigung zulässig"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Vorbereitende Signale, kein Mandat', '[["Plattform-Ausschreibung 2023", "Bestätigt über das bahrainische Tender Board selbst (305/2023/BTB): ein 54-monatiger Vertrag zur Konzeption/zum Betrieb einer E-Invoicing-Plattform"], ["Ausschreibung 2025 (berichtet)", "Eine weitere Ausschreibung für ein landesweites B2B-System wurde in einem Branchenbericht erwähnt -- konnte in dieser Runde nicht unabhängig bestätigt werden"], ["Erwartetes Modell", "Branchenkommentare spekulieren über einen Ansatz nach saudi-arabischem ZATCA-Vorbild -- keine offizielle Entscheidung der bahrainischen Regierung"], ["Peppol-Mitgliedschaft", "Bahrain ist kein Peppol-Mitglied"]]', 'Eine staatliche Ausschreibung zum Aufbau einer Plattform ist eine reale vorbereitende Aktivität, aber weder ein Gesetz noch ein Mandat noch eine datierte rechtliche Anforderung -- sie wird hier der Vollständigkeit halber aufgeführt, nicht als Beleg dafür, dass ein Mandat unmittelbar bevorsteht.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚖️ Es existiert kein Bußgeldkatalog für die E-Rechnungsstellung', NULL, NULL, 'Auf der Seite der E-Rechnungsstellung gibt es nichts zu sanktionieren: Bahrain hat nie ein E-Invoicing-Mandat gesetzlich verankert, sodass kein Bußgeld- oder Sanktionskatalog daran anknüpft, wie (oder ob) Sie Rechnungen elektronisch ausstellen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 Bahrains allgemeine Mehrwertsteuersanktionen (nicht im Zusammenhang mit der E-Rechnungsstellung)', NULL, NULL, 'Das gewöhnliche Mehrwertsteuerrecht Bahrains sieht eigene allgemeine Sanktionen vor -- verspätete Einreichung/Zahlung (5-25 % der geschuldeten Steuer), Registrierungsversäumnis (Geldbuße bis zu BHD 10.000), Verstöße gegen Rechnungsverfahren (Geldbuße bis zu BHD 5.000) sowie Steuerhinterziehung einschließlich Nichtausstellung von Rechnungen (Freiheitsstrafe zuzüglich Geldbußen). Diese gelten allgemein für die Mehrwertsteuer-Compliance und sind nicht spezifisch für die E-Rechnungsstellung; die Zahlen stammen aus einer sekundären Compliance-Quelle und wurden in dieser Rechercherunde nicht unabhängig gegen den primären Text des Mehrwertsteuergesetzes erneut verifiziert.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🌍 Kontext: einer von zwei GCC-Staaten ganz ohne Mandat', NULL, NULL, 'Saudi-Arabiens Fatoora-System ist live und ausgereift; die VAE führen ab Juli 2026 schrittweise ein Peppol-basiertes B2B-Mandat ein; Oman hat ein laufendes Pilotprojekt; Katar hat am 6. Mai 2026 einen Gesetzentwurf verabschiedet. Bahrain und Kuwait sind nun die einzigen beiden GCC-Staaten ohne jeglichen formellen Schritt in Richtung E-Rechnungsstellung.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Es gibt heute nichts zu erfüllen', 'In Bahrain besteht kein E-Invoicing-Mandat, weder vorgeschlagen noch erlassen. Es ist keine Registrierung, Meldung oder Formatänderung erforderlich.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Die E-Rechnungsstellung ist freiwillig verfügbar, ohne dass eine Genehmigung erforderlich ist', 'Seit November 2023 kann jedes mehrwertsteuerlich registrierte Unternehmen elektronische Rechnungen ausstellen, ohne die vorherige Genehmigung der NBR einzuholen -- aber niemand ist dazu verpflichtet, und es wird kein Format oder keine Plattform vorgeschrieben.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Achten Sie auf einen echten Vorschlag, nicht nur auf eine Ausschreibung', 'Bahrain hat staatliche Ausschreibungen für die Infrastruktur einer E-Invoicing-Plattform veröffentlicht, aber eine Ausschreibung ist kein Mandat. Achten Sie speziell auf eine Änderung des Mehrwertsteuergesetzentwurfs oder eine Mandatsankündigung der NBR.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Rechnen Sie damit, dass Bahrain letztlich dem regionalen Vorbild folgt', 'Da Saudi-Arabien, die VAE, Oman und nun auch Katar bei der E-Rechnungsstellung vorankommen, wird Bahrain wahrscheinlich irgendwann folgen -- aber nichts bestätigt offiziell einen Zeitplan, und diese Seite wird darüber nicht spekulieren.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Merken Sie sich diese Seite', 'Dieser Tracker wird einen echten Meilenstein und einen ordentlichen Compliance-Zeitplan hinzufügen, sobald Bahrain einen tatsächlichen E-Invoicing-Vorschlag oder Gesetzentwurf veröffentlicht.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'National Bureau for Revenue (NBR) -- allgemeine Mehrwertsteuerverwaltung; keine Inhalte zu einem E-Invoicing-Mandat' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.nbr.gov.bh';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'Fonoa -- Zusammenfassung der Aufhebung des Genehmigungserfordernisses vom November 2023 (Branchenquelle, nicht staatlich veröffentlicht)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.fonoa.com/resources/blog/bahrain-eliminates-tax-authority-approval-requirement-for-e-invoice-issuance';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bh-prior-approval-removed-2023', 'de',
  'Die NBR hebt das Genehmigungserfordernis für freiwillige E-Rechnungsstellung auf -- weiterhin kein Mandat',
  'Am 16. November 2023 aktualisierte Bahrains National Bureau for Revenue (NBR) seinen VAT General Guide (Version 1.8, Abschnitt 9.2), um mehrwertsteuerlich registrierten Unternehmen zu erlauben, elektronische Rechnungen auszustellen, ohne zuvor die Genehmigung der NBR einzuholen. Dies ist eine reale, datierte, durch Primärquellen bestätigte Verfahrensänderung -- sie hat jedoch lediglich einen bürokratischen Vorabfreigabeschritt für eine rein freiwillige Praxis abgeschafft; sie hat kein E-Invoicing-Mandat, keine Plattform, keine Formatanforderung und keine Frist geschaffen. Es existiert derzeit (Stand dieser Rechercherunde, August 2026) kein Gesetzentwurf, keine Änderung des Mehrwertsteuergesetzes und keine erlassene Verordnung, die ein E-Invoicing-Mandat für Bahrain begründen würde. Zwei unabhängig direkt geprüfte professionelle Tracker -- EYs eigener eInvoicing-Entwicklungs-Tracker (Ausgabe vom 24. Juni 2026) und Aurifer, ein auf den Nahen Osten spezialisierter Experte für indirekte Steuern -- stufen Bahrain weiterhin als Land ohne anwendbares Mandat ein, das sich lediglich in der "vorbereitenden Arbeit" befindet. Eine staatliche Ausschreibung aus dem Jahr 2023 für eine E-Invoicing-Plattform sowie unbestätigte Berichte über eine weitere Ausschreibung 2025 deuten auf vorbereitende Aktivitäten im Hintergrund hin, sind aber weder ein Gesetz noch eine datierte Anforderung.',
  '["Es ist keine Compliance-Maßnahme erforderlich -- die E-Rechnungsstellung bleibt in Bahrain vollständig freiwillig, ohne dass ein Mandat vorgeschlagen oder erlassen wurde", "Beobachten Sie den VAT General Guide der NBR und das Amtsblatt auf einen künftigen Mandatsvorschlag -- derzeit existiert keiner", "Beachten Sie, dass Bahrain nun neben Kuwait der einzige GCC-Staat ohne aktives oder bevorstehendes E-Invoicing-Mandat ist, da Saudi-Arabien, die VAE, Oman und (als Gesetzentwurf) Katar sich allesamt in Bewegung befinden"]'
);

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Aucun mandat — la facturation électronique reste entièrement volontaire, sans projet de loi, proposition ni calendrier d''aucune sorte',
  'Cette page d''analyse approfondie reflète le régime de facturation électronique de Bahreïn, tel que confirmé via le propre Guide général de la TVA du Bureau national des recettes (NBR), deux organismes de veille professionnels indépendants (EY, Aurifer) et les propres registres de la Commission des appels d''offres de Bahreïn, à la date du 10 août 2026, et est fourni à titre d''information générale, non comme un conseil juridique ou fiscal. Bahreïn n''a aucun mandat de facturation électronique, aucun projet de loi ni aucun calendrier publié officiellement d''aucune sorte — tout ce qui figure sur cette page décrit une pratique volontaire et une activité gouvernementale préparatoire, et non une exigence en vigueur ou à venir. Confirmez le statut actuel directement auprès du Bureau national des recettes de Bahreïn (nbr.gov.bh) ou d''un conseiller fiscal bahreïni qualifié avant de vous fier à cette page pour vos décisions de planification.',
  'Le seul événement daté et confirmé par une source primaire sur cette chronologie est un changement procédural mineur : le 16 novembre 2023, la NBR a supprimé l''obligation pour les entreprises d''obtenir une approbation préalable avant d''émettre volontairement des factures électroniques. C''est tout — il n''y a aucun autre jalon spécifique à la facturation électronique, antérieur ou postérieur, à afficher, car rien d''autre ne s''est produit. Deux organismes de veille professionnels indépendants consultés directement mi-2026 (EY, Aurifer) classent tous deux encore Bahreïn comme un pays sans mandat applicable, en simple « travail préparatoire ».',
  'Aucun format, schéma ou norme technique de facturation électronique n''existe pour Bahreïn, car la facturation électronique est entièrement volontaire et non réglementée au-delà des règles ordinaires de facturation en matière de TVA. Il n''existe aucune plateforme de facturation électronique de la NBR, et il est confirmé que Bahreïn n''est pas membre de Peppol.',
  'Aucun périmètre n''a jamais été défini pour un mandat de facturation électronique bahreïni, car aucun mandat n''a jamais été proposé. Les règles ordinaires de facturation en matière de TVA s''appliquent uniformément au B2B, au B2G et au B2C, sans aucune exigence de format électronique.',
  'Il n''y a rien à respecter aujourd''hui, ni rien à l''horizon avec une date publiée. Les étapes ci-dessous décrivent comment rester informé étant donné que les voisins de Bahreïn avancent en matière de facturation électronique, et non comment se conformer à une exigence qui n''existe pas.',
  'Aucun barème de sanctions spécifique à la facturation électronique n''a jamais été proposé ni publié, puisqu''il n''existe aucune exigence de facturation électronique à laquelle rattacher une sanction. Bahreïn dispose bien de sanctions générales prévues par la loi sur la TVA pour des questions sans rapport (dépôt tardif, manquements à l''immatriculation, infractions aux procédures de facturation, évasion fiscale) — celles-ci sont mentionnées ci-dessous par souci d''exhaustivité, mais ne constituent pas des sanctions de facturation électronique, et les chiffres précis n''ont pas été revérifiés de manière indépendante par rapport au texte primaire de la loi sur la TVA lors de cette phase de recherche.',
  'Bahreïn n''a aucun mandat de facturation électronique, aucun projet de loi ni aucun calendrier publié officiellement, d''aucune sorte. Le seul fait confirmé et daté est un changement procédural mineur de novembre 2023 : la NBR a supprimé l''obligation de solliciter une approbation préalable avant d''émettre volontairement des factures électroniques — la facturation électronique reste entièrement volontaire. Deux organismes de veille professionnels indépendants consultés mi-2026 (EY, Aurifer) classent tous deux Bahreïn comme étant toujours en « travail préparatoire », aux côtés du Koweït, tandis que l''Arabie saoudite, les Émirats arabes unis et Oman disposent tous de mandats actifs ou imminents et que le Qatar a au moins approuvé un projet de loi. Un appel d''offres gouvernemental de 2023 pour une plateforme de facturation électronique, ainsi qu''un rapport non confirmé faisant état d''un nouvel appel d''offres en 2025, laissent entrevoir une activité préparatoire en coulisses, mais ni l''un ni l''autre ne constitue une loi. Ce suivi sera mis à jour immédiatement dès qu''une véritable proposition, un projet de loi ou un calendrier sera officiellement publié.',
  '📝'
FROM countries WHERE code = 'BH';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucun mandat', 'Statut de la loi sur la facturation électronique' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Volontaire uniquement', 'Base actuelle de la facturation électronique à Bahreïn' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '16 nov. 2023', 'La NBR supprime l''obligation d''approbation préalable pour la facturation électronique volontaire' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucun publié', 'Proposition de mandat, projet de loi ou calendrier de quelque nature que ce soit' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '« Travail préparatoire »', 'Selon les propres outils de veille d''EY et d''Aurifer, tous deux datant de mi-2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'BH' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Aucun format n''existe — car la facturation électronique reste volontaire', NULL, NULL, 'Bahreïn n''a jamais publié de schéma de facturation électronique, de norme XML/UBL ni de spécification technique. Il n''existe aucune plateforme de facturation électronique de la NBR, et il est confirmé que Bahreïn n''est pas membre du réseau Peppol. Les entreprises qui émettent volontairement des factures électroniques le font sur leurs propres systèmes, selon les règles ordinaires de facturation en matière de TVA, et non selon un format spécifique à la facturation électronique.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce qui est couvert aujourd''hui', '[["B2B", "Non défini -- aucun mandat n''existe"], ["B2G", "Non défini -- aucun mandat n''existe"], ["B2C", "Non défini -- aucun mandat n''existe"], ["Facturation électronique volontaire", "Autorisée sans approbation préalable de la NBR depuis le 16 novembre 2023"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Signaux préparatoires, pas un mandat', '[["Appel d''offres pour une plateforme (2023)", "Confirmé via la Commission des appels d''offres de Bahreïn elle-même (305/2023/BTB) : un contrat de 54 mois pour concevoir/exploiter une plateforme de facturation électronique"], ["Appel d''offres 2025 (rapporté)", "Un nouvel appel d''offres pour un système B2B à l''échelle nationale a été rapporté par une note sectorielle -- n''a pas pu être corroboré de manière indépendante lors de cette phase"], ["Modèle envisagé", "Les commentaires du secteur spéculent sur une approche de type ZATCA saoudienne -- il ne s''agit pas d''une décision officielle du gouvernement bahreïni"], ["Adhésion à Peppol", "Bahreïn n''est pas membre de Peppol"]]', 'Un appel d''offres gouvernemental pour construire une plateforme constitue une activité préparatoire réelle, mais ce n''est ni une loi, ni un mandat, ni une exigence juridique datée -- il est inclus ici par souci d''exhaustivité, non comme preuve qu''un mandat serait imminent.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚖️ Aucun barème de sanctions pour la facturation électronique n''existe', NULL, NULL, 'Il n''y a rien à sanctionner du côté de la facturation électronique : Bahreïn n''a jamais légiféré sur un mandat de facturation électronique, de sorte qu''aucun barème d''amendes ou de sanctions n''est rattaché à la manière (ou à la question de savoir si) vous émettez des factures électroniquement.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 Sanctions générales en matière de TVA à Bahreïn (sans rapport avec la facturation électronique)', NULL, NULL, 'Le droit ordinaire de la TVA à Bahreïn comporte ses propres sanctions générales -- dépôt/paiement tardif (5-25 % de la taxe due), défaut d''immatriculation (amende pouvant atteindre 10 000 BHD), infractions aux procédures de facturation (amende pouvant atteindre 5 000 BHD), et évasion fiscale, y compris la non-émission de factures (emprisonnement assorti d''amendes). Ces sanctions s''appliquent à la conformité en matière de TVA de manière générale et ne sont pas spécifiques à la facturation électronique ; les chiffres proviennent d''une source de conformité secondaire et n''ont pas été revérifiés de manière indépendante par rapport au texte primaire de la loi sur la TVA lors de cette phase de recherche.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🌍 Contexte : l''un des deux États du CCG sans aucun mandat', NULL, NULL, 'Le système Fatoora de l''Arabie saoudite est opérationnel et mature ; les Émirats arabes unis déploient progressivement un mandat B2B basé sur Peppol à partir de juillet 2026 ; Oman dispose d''un pilote opérationnel ; le Qatar a approuvé un projet de loi le 6 mai 2026. Bahreïn et le Koweït sont désormais les deux seuls États du CCG à n''avoir franchi aucune étape formelle vers la facturation électronique.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'BH' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Il n''y a rien à respecter aujourd''hui', 'Aucun mandat de facturation électronique n''existe à Bahreïn, ni proposé ni promulgué. Aucune immatriculation, déclaration ou modification de format n''est requise.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'La facturation électronique est disponible sur une base volontaire, sans approbation nécessaire', 'Depuis novembre 2023, toute entreprise immatriculée à la TVA peut émettre des factures électroniques sans solliciter l''approbation préalable de la NBR -- mais rien ne vous y oblige, et aucun format ni plateforme n''est imposé.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez l''apparition d''une véritable proposition, pas seulement d''un appel d''offres', 'Bahreïn a publié des appels d''offres gouvernementaux pour l''infrastructure d''une plateforme de facturation électronique, mais un appel d''offres n''est pas un mandat. Surveillez spécifiquement un projet de modification de la loi sur la TVA ou une annonce de mandat de la NBR.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Attendez-vous à ce que Bahreïn suive éventuellement le précédent régional', 'Alors que l''Arabie saoudite, les Émirats arabes unis, Oman et désormais le Qatar avancent tous en matière de facturation électronique, Bahreïn devrait probablement finir par suivre -- mais rien ne confirme officiellement un calendrier, et cette page ne spéculera pas à ce sujet.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ajoutez cette page à vos favoris', 'Ce suivi ajoutera un véritable jalon et un calendrier de conformité approprié dès que Bahreïn publiera une véritable proposition ou un projet de loi de facturation électronique.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'BH' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'Bureau national des recettes (NBR) -- administration générale de la TVA ; aucun contenu relatif à un mandat de facturation électronique' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.nbr.gov.bh';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'Fonoa -- résumé de la suppression de l''obligation d''approbation préalable de novembre 2023 (source sectorielle, non publiée par le gouvernement)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'BH' AND p.url = 'https://www.fonoa.com/resources/blog/bahrain-eliminates-tax-authority-approval-requirement-for-e-invoice-issuance';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'bh-prior-approval-removed-2023', 'fr',
  'La NBR supprime l''obligation d''approbation préalable pour la facturation électronique volontaire -- toujours aucun mandat',
  'Le 16 novembre 2023, le Bureau national des recettes de Bahreïn (NBR) a mis à jour son Guide général de la TVA (version 1.8, section 9.2) pour permettre aux entreprises immatriculées à la TVA d''émettre des factures électroniques sans devoir au préalable obtenir l''approbation de la NBR. Il s''agit d''un changement procédural réel, daté et confirmé par une source primaire -- mais il a seulement supprimé une étape bureaucratique de préautorisation pour une pratique purement volontaire ; il n''a créé ni mandat de facturation électronique, ni plateforme, ni exigence de format, ni échéance. Aucun projet de loi, aucune modification de la loi sur la TVA et aucun règlement promulgué instaurant un mandat de facturation électronique n''existe pour Bahreïn à la date de cette phase de recherche (août 2026). Deux organismes de veille professionnels indépendants consultés directement -- le propre suivi des évolutions en matière de facturation électronique d''EY (édition du 24 juin 2026) et Aurifer, spécialiste de la fiscalité indirecte au Moyen-Orient -- classent tous deux encore Bahreïn comme un pays sans mandat applicable, en simple « travail préparatoire ». Un appel d''offres gouvernemental de 2023 pour une plateforme de facturation électronique, ainsi que des informations non confirmées faisant état d''un nouvel appel d''offres en 2025, indiquent une activité préparatoire en coulisses, mais ni l''un ni l''autre ne constitue une loi ni une exigence datée.',
  '["Aucune action de conformité n''est requise -- la facturation électronique reste entièrement volontaire à Bahreïn, sans mandat proposé ni promulgué", "Surveillez le Guide général de la TVA de la NBR et le Journal officiel pour toute future proposition de mandat -- aucune n''existe actuellement", "Notez que Bahreïn est désormais, avec le Koweït, le seul État du CCG sans mandat de facturation électronique actif ni imminent, alors que l''Arabie saoudite, les Émirats arabes unis, Oman et (sous forme de projet de loi) le Qatar avancent tous sur ce sujet"]'
);
